"""Build mt5/Saad_exhaust.mq5 = Saad_meta + in-trade exhaustion exit (Zee 2026-10-13, "In-Trade Exhaustion Classifier").
At every new M15 candle, for every open position:
  * InpExhLog  - log its state to Common\\Files\\saad_exh_<InpMetaTag>.csv (with InpMetaLog=true the trade's
                 final result goes to saad_meta_<tag>_out.csv). The label is built in Python from those two
                 files only: 1 if closing NOW would have made more than the way the trade really ended.
  * InpExhMode=1 - the trained XGBoost trees compiled into the EA (SaadExhaustModel.mqh, generated by
                 meta_labeling_system/src/train_exhaustion.py); close the position when P >= InpExhThr.
                 Like the pasted spec, only positions currently in profit are judged (InpExhProfitOnly)."""
src = r'C:\Users\zeesh\turtle\mt5\Saad_meta.mq5'
dst = r'C:\Users\zeesh\turtle\mt5\Saad_exhaust.mq5'
s = open(src, encoding='utf-8').read()


def rep(a, b):
    global s
    assert s.count(a) == 1, (s.count(a), a[:80])
    s = s.replace(a, b)


rep('#include "SaadMetaModel.mqh"', '#include "SaadMetaModel.mqh"\n#include "SaadExhaustModel.mqh"')
rep("input int    InpMetaMode    = 0;",
    """input int    InpExhMode     = 0;      // InpExhMode — in-trade exhaustion exit: 0 off · 1 model compiled into the EA
input double InpExhThr      = 0.85;   // InpExhThr — close when the model's "closing now beats holding" probability is at least this
input bool   InpExhProfitOnly = true; // InpExhProfitOnly — judge only positions currently in profit (the pasted spec)
input bool   InpExhLog      = false;  // InpExhLog — log every open position's state at each candle close (training data)
input int    InpMetaMode    = 0;""")
rep("int g_metaVeto = 0;", "int g_metaVeto = 0;\nint g_exhCloses = 0, g_exhLog = INVALID_HANDLE;")

rep("void DoEntry(int side, double sl)\n{", r'''//--- in-trade exhaustion -----------------------------------------------------
// state of position i at the close of the candle that just closed; order MUST match EXH_NAMES in train_exhaustion.py
bool ExhFeatures(int i, double &x[], double &flt, double &realized)
{
   if (!PositionSelectByTicket(g_pos[i].ticket)) return false;
   ArrayResize(x, EXH_NF);
   int side = g_pos[i].side;
   double atr = Buf(hAtr, 1), atr200 = Buf(hAtr200, 1); if (atr <= 0) return false;
   double risk = MathAbs(g_pos[i].entry - g_pos[i].sl0); if (risk <= 0) risk = atr;
   double px = side > 0 ? SymbolInfoDouble(_Symbol, SYMBOL_BID) : SymbolInfoDouble(_Symbol, SYMBOL_ASK);
   double c1 = iClose(_Symbol, PERIOD_CURRENT, 1), o1 = iOpen(_Symbol, PERIOD_CURRENT, 1);
   double net = MathAbs(c1 - iClose(_Symbol, PERIOD_CURRENT, 15)), path = 0;
   for (int k = 1; k <= 14; k++) path += MathAbs(iClose(_Symbol, PERIOD_CURRENT, k) - iClose(_Symbol, PERIOD_CURRENT, k + 1));
   double sl = PositionGetDouble(POSITION_SL);
   double fr = side * (px - g_pos[i].entry) / risk, mr = side * (g_pos[i].mfe - g_pos[i].entry) / risk;
   MqlDateTime dt; TimeToStruct(TimeCurrent(), dt);
   x[0]  = side;
   x[1]  = (double)(TimeCurrent() - g_pos[i].entryTime) / PeriodSeconds();     // candles held
   x[2]  = fr;                                                                   // open profit in R
   x[3]  = mr;                                                                   // best so far in R
   x[4]  = mr - fr;                                                              // given back from the best, R
   x[5]  = path > 0 ? net / path : 0;                                            // ER(14) now
   x[6]  = side * (c1 - Ema(50, 1)) / atr;                                       // distance to the 50 EMA, trade way +
   x[7]  = side * (c1 - Ema(9, 1)) / atr;                                        // distance to the 9 EMA
   x[8]  = atr200 > 0 ? atr / atr200 : 1;                                        // ATR14 / ATR200
   x[9]  = g_pos[i].usdTrail ? 1 : (g_pos[i].ride ? 2 : 0);                      // 0 before TP1 · 1 after TP1 ($ trail) · 2 riding
   x[10] = sl > 0 ? side * (px - sl) / risk : 0;                                 // room to the stop, R
   x[11] = side * (c1 - o1) / atr;                                               // last candle body, trade way +
   x[12] = dt.hour;
   x[13] = PositionGetDouble(POSITION_VOLUME) / MathMax(InpLots, 0.01);          // share of the position still open
   flt = PositionGetDouble(POSITION_PROFIT);
   realized = 0;
   if (HistorySelectByPosition(g_pos[i].ticket))
      for (int k = 0; k < HistoryDealsTotal(); k++) {
         ulong d = HistoryDealGetTicket(k);
         if (HistoryDealGetInteger(d, DEAL_ENTRY) != DEAL_ENTRY_IN) realized += HistoryDealGetDouble(d, DEAL_PROFIT);
      }
   return true;
}
void ExhaustBar()
{
   if (InpExhMode <= 0 && !InpExhLog) return;
   if (InpExhLog && g_exhLog == INVALID_HANDLE) {
      string fn = StringFormat("saad_exh_%d.csv", InpMetaTag);
      if (MQLInfoInteger(MQL_TESTER)) FileDelete(fn, FILE_COMMON);
      g_exhLog = FileOpen(fn, FILE_READ | FILE_WRITE | FILE_TXT | FILE_COMMON | FILE_SHARE_READ | FILE_ANSI);
      if (g_exhLog != INVALID_HANDLE) {
         FileSeek(g_exhLog, 0, SEEK_END);
         if (FileSize(g_exhLog) == 0) { string h = "pos_id,time"; for (int k = 0; k < EXH_NF; k++) h += "," + EXH_NAMES[k]; FileWriteString(g_exhLog, h + ",float_usd,realized_usd,prob,closed\r\n"); }
      }
   }
   for (int i = ArraySize(g_pos) - 1; i >= 0; i--) {
      if (g_pos[i].entryTime >= iTime(_Symbol, PERIOD_CURRENT, 0)) continue;   // opened on this same candle
      double x[], flt, rl;
      if (!ExhFeatures(i, x, flt, rl)) continue;
      double p = -1; int closed = 0;
      if (InpExhMode == 1 && (!InpExhProfitOnly || flt > 0)) {
         p = ExhModelProb(x);
         if (p >= InpExhThr) {
            g_pos[i].why = StringFormat("exhaustion model %.2f", p);
            Log(StringFormat("#%d EXHAUSTION %.2f >= %.2f -> closing at $%.2f open profit", g_pos[i].num, p, InpExhThr, flt));
            if (trade.PositionClose(g_pos[i].ticket)) { g_exhCloses++; closed = 1; }
         }
      }
      if (g_exhLog != INVALID_HANDLE) {
         string r = StringFormat("%I64u,%s", g_pos[i].ticket, TimeToString(TimeCurrent(), TIME_DATE | TIME_SECONDS));
         for (int k = 0; k < EXH_NF; k++) r += StringFormat(",%.8f", x[k]);
         FileWriteString(g_exhLog, r + StringFormat(",%.2f,%.2f,%.8f,%d\r\n", flt, rl, p, closed));
      }
   }
}

void DoEntry(int side, double sl)
{''')
rep("      g_lastBar = bar;\n", "      g_lastBar = bar;\n      ExhaustBar();\n      SyncPos();\n")
rep('   PrintFormat("[SAAD-META] vetoed %d trades',
    '   PrintFormat("[SAAD-EXH] mode %d: closed %d positions on the exhaustion model (threshold %.2f)", InpExhMode, g_exhCloses, InpExhThr);\n'
    '   if (g_exhLog != INVALID_HANDLE) FileClose(g_exhLog);\n'
    '   PrintFormat("[SAAD-META] vetoed %d trades')
open(dst, 'w', encoding='utf-8').write(s)
print('wrote', dst)
